"""TASK-20261002-f19cfa (red team, J2 and J3 of REVIEW-NISTBIN-20261002-bc5bd5).

Independent closed-form review computations. Written by this reviewer from the
contract's stated formulas (EXP-NISTBIN-451dfa version 4 definitions) and the
primary inputs; it imports nothing from the producer's code blocks and does not
load experiments/EXP-SEMBIN-81dc96/code/joint_balance.py. No curve or group is
constructed, no solver runs, nothing under experiments/*/runs/ is opened.

Exactness: binomial partial sums are Python integers; every per-step, DELTA7
and M7-versus-R-B comparison is decided by exact integer inequality; every
margin involving pi, exp or log is evaluated with mpmath at 256 bits.
"""
import json, math, sys, hashlib, re
from fractions import Fraction
import mpmath as mp

mp.mp.prec = 256
N571 = 571
OMEGA = mp.mpf(3)
M_LO, M_HI = 2, 30
D_LO, D_HI = 2, 64
REPO = "/home/user/crypto-autoresearcher"
FIPS_TEXT = REPO + "/inputs/FIPS186-4-BINARY-CURVES/fips186-4_text.md"

# --------------------------------------------------------------------------
# Primary inputs
# FIPS 186-4 D.1.3 base-point orders, transcribed by this reviewer from the
# primary text (decimal), each verified below to occur in the flattened text.
FIPS_R = {
    "K-163": "5846006549323611672814741753598448348329118574063",
    "B-163": "5846006549323611672814742442876390689256843201587",
    "K-233": "3450873173395281893717377931138512760570940988862252126328087024741343",
    "B-233": "6901746346790563787434755862277025555839812737345013555379383634485463",
    "K-283": "3885337784451458141838923813647037813284811733793061324295874997529815829704422603873",
    "B-283": "7770675568902916283677847627294075626569625924376904889109196526770044277787378692871",
    "K-409": ("33052798439512429947595765401638551991420234148214060964"
              "2324395022880711289249191050673258457777458014096366590617731358671"),
    "B-409": ("6610559687902485989519153080327710398284046829642812192"
              "84648798304157774827374805208143723762179110965979867288366567526771"),
    "K-571": ("1932268761508629172347675945465993672149463664853217499"
              "32861762572575957114478021226813397852270671183470671280"
              "08253514612736749740666173119296824216170925035557336852"
              "76673"),
    "B-571": ("3864537523017258344695351890931987344298927329706434998"
              "65723525145151914228956042453614399938941577308313388112"
              "19269444862468724628168130702345282883033324113931911052"
              "85703"),
}
# FIPS preamble: pseudo-random curves h = 2; Koblitz h = 2 if a = 1, h = 4 if
# a = 0 (K-163 a = 1; K-233, K-283, K-409, K-571 a = 0). k_c = n for Koblitz
# curves over F_2 (contract definitions.rho), 1 otherwise.
FIPS_H = {"K-163": 2, "B-163": 2, "K-233": 4, "B-233": 2, "K-283": 4, "B-283": 2,
          "K-409": 4, "B-409": 2, "K-571": 4, "B-571": 2}


def fips_curves():
    raw = open(FIPS_TEXT, "rb").read()
    flat = re.sub(r"[\s\\]", "", raw.decode("utf-8"))
    out = {}
    for lab, rs in FIPS_R.items():
        n = int(lab.split("-")[1])
        r = int(rs)
        h = FIPS_H[lab]
        dev = h * r - (2 ** n + 1)
        out[lab] = {"n": n, "r": r, "h": h, "k_c": n if lab.startswith("K") else 1,
                    "found_in_text": rs in flat, "hasse_ok": dev * dev <= 4 * 2 ** n,
                    "r_bits": r.bit_length()}
    return hashlib.sha256(raw).hexdigest(), out


def certicom_curves(path):
    o = json.load(open(path))
    out = {}
    for c in o["curves"]:
        if c.get("m") is None or "r_dec" not in c:
            continue
        lab = c["label"]
        koblitz = lab.startswith("ECC2K")
        out[lab] = {"n": c["m"], "r": int(c["r_dec"]), "h": c.get("h"),
                    "k_c": c["m"] if koblitz else 1, "hasse_ok": c.get("hasse_ok"),
                    "r_bits": c.get("r_bits"), "block_line": c["block_line"]}
    return o["input_sha256"], out


def rho(curve):
    return mp.mpf("0.5") * mp.log(mp.pi * curve["r"] / (4 * curve["k_c"]), 2)


# --------------------------------------------------------------------------
# Cost model (contract definitions A, W, reading_R_B, reading_R_M, M7-BIN)
def k_of(n, m, kr):
    if kr == "MI-1":
        return Fraction(n, m)
    if kr == "ceiled":
        return Fraction(-(-n // m))
    if kr == "floor":
        return Fraction(n // m)
    raise ValueError(kr)


def neg_log2_P(n, m, kr, pf):
    k = k_of(n, m, kr)
    e = m * k - n
    log2x = mp.mpf(e.numerator) / e.denominator - mp.log(math.factorial(m), 2)
    if pf == "PF-1":
        return -log2x
    x = mp.power(2, log2x)
    return -mp.log(-mp.expm1(-x), 2)


def A(n, m, kr, pf):
    k = k_of(n, m, kr)
    return mp.mpf(k.numerator) / k.denominator + neg_log2_P(n, m, kr, pf)


def C_I(n, omega, kr="MI-1", pf="PF-2"):
    best = None
    for m in range(M_LO, min(M_HI, n) + 1):
        v = A(n, m, kr, pf) + 4 * omega * mp.log(n, 2)
        if best is None or v < best[0]:
            best = (v, m)
    return best


_PS = {}


def psums(N, dmax=D_HI):
    """Exact partial sums S(N, D) = sum_{d<=D} binom(N, d), D = 0..dmax."""
    key = N
    if key not in _PS:
        s, out = 0, []
        for d in range(dmax + 1):
            s += math.comb(N, d)
            out.append(s)
        _PS[key] = out
    return _PS[key]


def W(N, D):
    return mp.log(psums(N)[D], 2)


def N5(m, kr, n=N571):
    k = k_of(n, m, kr)
    return m * k + (m - 2) * n   # Fraction


def S_B(D, omega=OMEGA, n=N571):
    return D * omega * mp.log(n, 2)


def S_M(D, omega=OMEGA, n=N571):
    return omega * (W(n, D) - W(n, 4) + 4 * mp.log(n, 2))


def S_7(D, N, omega=OMEGA, n=N571):
    if D <= 4:
        return S_B(D, omega, n)
    return omega * (4 * mp.log(n, 2) + W(N, D) - W(N, 4))


def crossing(a, rho_c, S):
    for D in range(D_LO, D_HI + 1):
        if a + S(D) - rho_c > 0:
            return D
    return None


def tok(d):
    if d is None:
        return "no crossing at D <= 64"
    if d == D_LO:
        return "D* <= 2"
    return d


def as_int(d):
    return D_HI + 1 if d is None else d


# --------------------------------------------------------------------------
# Exact M7-BIN crossovers (integer comparisons; n = 571)
def dps_dcum(N, n=N571):
    S = psums(N)
    d_ps = next((D for D in range(5, D_HI + 1) if S[D] < n * S[D - 1]), None)
    d_cum = next((D for D in range(5, D_HI + 1) if S[D] < S[4] * n ** (D - 4)), None)
    return d_ps, d_cum


def delta7_sign(N, D, n=N571):
    """sign of DELTA7(D) = [W(N, D) - W(N, 4)] - (D - 4) log2 n, exactly."""
    S = psums(N)
    lhs, rhs = S[D], S[4] * n ** (D - 4)
    return (lhs > rhs) - (lhs < rhs)


def delta7(N, D, n=N571):
    return (W(N, D) - W(N, 4)) - (D - 4) * mp.log(n, 2)


def concave_exact(N, lo=4, hi=D_HI):
    """log-concavity of the partial sums on lo..hi: S(D)^2 >= S(D-1) S(D+1)."""
    S = psums(N)
    return all(S[D] * S[D] >= S[D - 1] * S[D + 1] for D in range(lo + 1, hi))


def m7_minmax(N, X, n=N571):
    """Over every rho at which the R-B crossing is X (rho in [A+S_B(X-1), A+S_B(X))),
    the least and the greatest M7-BIN crossing, decided exactly (A and omega
    cancel). min = least D with S_7(D) > S_B(X-1); max = least D with
    S_7(D) >= S_B(X). Returns (min, max) with None for 'none in 2..64'."""
    S = psums(N)

    def s7_gt_sb(D, Y):     # S_7(D) > S_B(Y)
        if D <= 4:
            return D > Y
        return S[D] > S[4] * n ** (Y - 4) if Y >= 4 else True

    def s7_ge_sb(D, Y):     # S_7(D) >= S_B(Y)
        if D <= 4:
            return D >= Y
        return S[D] >= S[4] * n ** (Y - 4) if Y >= 4 else True

    lo = next((D for D in range(D_LO, D_HI + 1) if s7_gt_sb(D, X - 1)), None)
    hi = next((D for D in range(D_LO, D_HI + 1) if s7_ge_sb(D, X)), None)
    return lo, hi

