"""TASK-20261002-f19cfa: driver for the J2 and J3 review computations.
Usage: python3 rt_run.py certicom_rows.json cb3_out.json > rt_out.json"""
import json, sys, math
from fractions import Fraction
import mpmath as mp
from rt_core import *

f2 = lambda x: float(mp.nstr(x, 12))
r4 = lambda x: round(float(x), 4)
out = {}

# ---------------------------------------------------------------- inputs
fips_sha, FC = fips_curves()
cert_sha, CC = certicom_curves(sys.argv[1])
cb3 = json.load(open(sys.argv[2]))
out["inputs"] = {"fips_text_sha256": fips_sha, "certicom_text_sha256": cert_sha,
                 "fips_rows": {k: {kk: (str(vv) if kk == "r" else vv) for kk, vv in v.items() if kk != "r"} | {"rho": r4(rho(v))} for k, v in FC.items()},
                 "certicom_rows": {k: {"n": v["n"], "h": v["h"], "k_c": v["k_c"], "r_bits": v["r_bits"], "hasse_ok": v["hasse_ok"], "rho": (r4(rho(v)) if v["h"] else None)} for k, v in CC.items()}}
RHO = {c: rho(FC[c]) for c in ("K-571", "B-571")}
out["rho_571"] = {c: f2(RHO[c]) for c in RHO}
out["rho_571_vs_cb3"] = {c: f2(RHO[c] - mp.mpf(cb3["rho_571"][c]["rho"])) for c in RHO}

# ---------------------------------------------------------------- A(571, m)
KRS = ("MI-1", "ceiled")
PFS = ("PF-2", "PF-1")
AT = {(kr, pf, m): A(N571, m, kr, pf) for kr in KRS + ("floor",) for pf in PFS for m in range(M_LO, M_HI + 1)}
cbA = {r["m"]: r for r in cb3["A_571_by_m"]}
maxdiff = 0.0
for m in range(M_LO, M_HI + 1):
    for kr, pf, key in (("MI-1", "PF-2", "A_MI1_PF2"), ("ceiled", "PF-2", "A_ceiled_PF2"), ("MI-1", "PF-1", "A_MI1_PF1"), ("ceiled", "PF-1", "A_ceiled_PF1")):
        maxdiff = max(maxdiff, abs(float(AT[(kr, pf, m)]) - cbA[m][key]))
out["A_571_check_vs_cb3_max_abs_diff_4dp_print"] = maxdiff

# ---------------------------------------------------------------- thresholds
LOG2N = mp.log(N571, 2)
WN = {D: W(N571, D) for D in range(0, D_HI + 1)}


def table(kr, pf):
    t = {}
    for c in ("K-571", "B-571"):
        for m in range(M_LO, M_HI + 1):
            a = AT[(kr, pf, m)]
            n5 = N5(m, kr)
            assert n5.denominator == 1
            n5 = int(n5)
            t[(c, "R-B", m)] = crossing(a, RHO[c], lambda D: S_B(D))
            t[(c, "R-M", m)] = crossing(a, RHO[c], lambda D: S_M(D))
            t[(c, "M7", m)] = crossing(a, RHO[c], lambda D, N=n5: S_7(D, N))
    return t


TAB = {(kr, pf): table(kr, pf) for kr in KRS for pf in PFS}
INF = TAB[("MI-1", "PF-2")]
CEIL = TAB[("ceiled", "PF-2")]
PF1 = TAB[("MI-1", "PF-1")]


def tabprint(t):
    rows = []
    for m in range(M_LO, M_HI + 1):
        rows.append({"m": m, **{f"{c}|{R}": tok(t[(c, R, m)]) for c in ("K-571", "B-571") for R in ("R-B", "R-M", "M7")}})
    return rows


out["threshold_table_in_force_MI1_PF2"] = tabprint(INF)
out["threshold_table_C_CEIL_T"] = tabprint(CEIL)
out["threshold_table_C_PF1_T"] = tabprint(PF1)


# minimum |margin| over every evaluated cell (precision guard)
def min_abs_margin():
    best = None
    for (kr, pf), t in TAB.items():
        for m in range(M_LO, M_HI + 1):
            a = AT[(kr, pf, m)]
            for c in ("K-571", "B-571"):
                for D in range(D_LO, D_HI + 1):
                    for nm, S in (("R-B", S_B(D)), ("R-M", S_M(D))):
                        v = abs(a + S - RHO[c])
                        if best is None or v < best[0]:
                            best = (v, kr, pf, m, c, nm, D)
    return {"min_abs_margin_bits": f2(best[0]), "at": list(best[1:])}


out["precision_guard_RB_RM"] = min_abs_margin()


# comparisons with CB-3 (counts, tokens, scored cells)
def compare(base, other):
    later = equal = earlier = 0
    mx = 0
    two = 0
    for key in [(c, R, m) for c in ("K-571", "B-571") for R in ("R-B", "R-M") for m in range(M_LO, M_HI + 1)]:
        d = as_int(other[key]) - as_int(base[key])
        if d > 0:
            later += 1; mx = max(mx, d); two += d >= 2
        elif d == 0:
            equal += 1
        else:
            earlier += 1
    return {"entries": later + equal + earlier, "later": later, "equal": equal, "earlier": earlier, "max_lateness": mx, "later_by_2_or_more": two}


out["table_comparisons"] = {"C-CEIL-T_vs_in_force": compare(INF, CEIL), "C-PF1-T_vs_in_force": compare(INF, PF1),
                            "ceiled_PF1_vs_in_force": compare(INF, TAB[("ceiled", "PF-1")])}
out["tokens"] = {f"{kr}|{pf}": {"D*<=2": sorted({(k[0], k[1], k[2]) for k, v in t.items() if v == D_LO and k[1] != "M7"}),
                                 "no_crossing": sorted({(k[0], k[1], k[2]) for k, v in t.items() if v is None and k[1] != "M7"}),
                                 "largest": max(as_int(v) for k, v in t.items() if k[1] != "M7")} for (kr, pf), t in TAB.items()}
mstar = C_I(N571, OMEGA)[1]
out["m_star_571"] = mstar
out["scored_cells"] = {f"{c}|{R}": tok(INF[(c, R, mstar)]) for c in ("K-571", "B-571") for R in ("R-B", "R-M")}
out["M8_check"] = all(as_int(INF[(c, R, m)]) <= as_int(INF[(c, R, mstar)]) for c in ("K-571", "B-571") for R in ("R-B", "R-M") for m in range(M_LO, M_HI + 1))

# ---------------------------------------------------------------- P-S
ps = {}
for name, t in (("in_force", INF), ("C-CEIL-T", CEIL), ("C-PF1-T", PF1)):
    rows = []
    neg = []
    for c in ("K-571", "B-571"):
        for m in range(M_LO, M_HI + 1):
            db, dm = as_int(t[(c, "R-B", m)]), as_int(t[(c, "R-M", m)])
            rows.append([c, m, tok(t[(c, "R-B", m)]), tok(t[(c, "R-M", m)]), dm - db])
            if dm - db < 0:
                neg.append({"curve": c, "m": m, "D*_B": tok(t[(c, "R-B", m)]), "D*_M": tok(t[(c, "R-M", m)]), "spread": dm - db, "R_M_crossing_at_D_ge_4": dm >= 4})
    ps[name] = {"per_entry": rows, "negative_spreads": neg,
                "negative_with_R_M_crossing_at_D_ge_4": sum(1 for x in neg if x["R_M_crossing_at_D_ge_4"]),
                "negative_with_R_B_crossing_at_D_ge_4": sum(1 for x in neg if (x["D*_B"] if isinstance(x["D*_B"], int) else 2) >= 4)}
out["P_S"] = ps
# K-571 m = 3 detail (S-2 (b))
a3 = AT[("MI-1", "PF-2", 3)]
out["P_S_K571_m3_margins"] = {f"R-{R}_D{D}": f2(a3 + (S_B(D) if R == "B" else S_M(D)) - RHO["K-571"]) for R in ("B", "M") for D in (2, 3, 4)}

# ---------------------------------------------------------------- PTM-I: crossovers
m7 = []
for kr in KRS + ("floor",):
    for m in range(M_LO, M_HI + 1):
        n5 = N5(m, kr)
        rec = {"k_reading": kr, "m": m, "N5_exact": str(n5)}
        roundings = {"round": int(round(n5)), "floor": math.floor(n5), "ceil": math.ceil(n5)}
        rec["N5_roundings_agree"] = len(set(roundings.values())) == 1
        N = roundings["round"]
        # float-path variants an implementation might use
        kf = 571 / m if kr == "MI-1" else float(k_of(571, m, kr))
        fl = m * kf + (m - 2) * 571
        rec["float_N5_truncation_int"] = int(fl)
        d_ps, d_cum = dps_dcum(N)
        rec["D_ps"] = d_ps if d_ps else "none in 5..64"
        rec["D_cum"] = d_cum if d_cum else "none in 5..64"
        rec["concave_exact_4_64"] = concave_exact(N)
        if d_cum:
            rec["DELTA7_at_Dcum_minus_1"] = r4(delta7(N, d_cum - 1))
            rec["DELTA7_at_Dcum"] = r4(delta7(N, d_cum))
            rec["sign_DELTA7_Dcum_minus_1"] = delta7_sign(N, d_cum - 1) if d_cum - 1 >= 5 else 0
        vals = [(delta7(N, D), D) for D in range(4, D_HI + 1)]
        mx = max(vals, key=lambda t: (t[0], -t[1]))
        rec["DELTA7_max"] = r4(mx[0]); rec["DELTA7_argmax"] = mx[1]
        # sensitivity probe outside the contract: N5 -1 / +1
        rec["probe_N5_minus_1"] = list(dps_dcum(N - 1))
        rec["probe_N5_plus_1"] = list(dps_dcum(N + 1))
        m7.append(rec)
out["PTM_I_crossovers"] = m7
# compare with CB-3 M7_crossovers (exact on the degree)
cbm7 = {(r["k_reading"], r["m"]): r for r in cb3["M7_crossovers"]}
mism = []
for rec in m7:
    if rec["k_reading"] == "floor":
        continue
    cr = cbm7[(rec["k_reading"], rec["m"])]
    for key in ("D_ps", "D_cum"):
        if cr[key] != rec[key]:
            mism.append([rec["k_reading"], rec["m"], key, cr[key], rec[key]])
    if int(cr["N5_rounded"]) != int(Fraction(rec["N5_exact"])):
        mism.append([rec["k_reading"], rec["m"], "N5", cr["N5_rounded"], rec["N5_exact"]])
    if cr["DELTA7_argmax"] != rec["DELTA7_argmax"] or abs(cr["DELTA7_max"] - rec["DELTA7_max"]) > 0.0002:
        mism.append([rec["k_reading"], rec["m"], "DELTA7max", [cr["DELTA7_max"], cr["DELTA7_argmax"]], [rec["DELTA7_max"], rec["DELTA7_argmax"]]])
out["PTM_I_vs_CB3_mismatches"] = mism

# ---------------------------------------------------------------- PTM-I: crossing cases (all rho levels)
cases = []
summary = {"cells": 0, "lemma_violations": 0, "b_cells_with_strictly_earlier_reachable": 0, "b_cells": 0,
           "b_cells_with_strictly_later_reachable": 0, "below_Dcum_later_reachable": 0, "below_Dcum_cells": 0,
           "Dcum_slot_cells": 0, "Dcum_slot_both_ways": 0, "above_Dcum_cells": 0, "above_Dcum_earlier_reachable": 0}
for kr in KRS:
    for m in range(M_LO, M_HI + 1):
        N = int(N5(m, kr))
        d_ps, d_cum = dps_dcum(N)
        for X in range(5, D_HI + 1):
            lo, hi = m7_minmax(N, X)
            lo_i, hi_i = as_int(lo), as_int(hi)
            region = ("a_below_Dps" if (d_ps is None or X < d_ps) else
                      "b_in_(Dps,Dcum]" if (d_cum is None or X <= d_cum) and X > d_ps else
                      "at_Dps" if X == d_ps else "c_above_Dcum")
            # lemma prediction
            sgnX = delta7_sign(N, X)
            sgnXm1 = delta7_sign(N, X - 1) if X - 1 >= 5 else 0
            pred_no_later = sgnX >= 0
            pred_no_earlier = sgnXm1 <= 0
            viol = (pred_no_later and hi_i > X) or (pred_no_earlier and lo_i < X)
            summary["cells"] += 1
            summary["lemma_violations"] += viol
            below = d_cum is None or X <= d_cum - 1
            if below:
                summary["below_Dcum_cells"] += 1
                summary["below_Dcum_later_reachable"] += hi_i > X
            if d_cum is not None and X == d_cum:
                summary["Dcum_slot_cells"] += 1
                summary["Dcum_slot_both_ways"] += (lo_i < X and hi_i > X)
            if d_cum is not None and X >= d_cum + 1:
                summary["above_Dcum_cells"] += 1
                summary["above_Dcum_earlier_reachable"] += lo_i < X
            if d_ps is not None and X > d_ps and (d_cum is None or X <= d_cum):
                summary["b_cells"] += 1
                summary["b_cells_with_strictly_earlier_reachable"] += lo_i < X
                summary["b_cells_with_strictly_later_reachable"] += hi_i > X
            if m in (6, 7, 8, 12, 30) or (X in (d_ps, d_cum) if d_cum else False):
                cases.append([kr, m, X, region, d_ps, d_cum, lo, hi, int(viol)])
out["PTM_I_crossing_cases_summary"] = summary
out["PTM_I_crossing_cases_sample"] = cases


# concrete rho cuts at both 571 rows (closed forms, mpmath margins), m = 12 and m = 8, MI-1 PF-2
def concrete(m, X, frac, kr="MI-1"):
    a = AT[(kr, "PF-2", m)]
    N = int(N5(m, kr))
    res = {}
    for c in ("K-571", "B-571"):
        lo_r = a + S_B(X - 1)
        hi_r = a + S_B(X)
        cut = lo_r + mp.mpf(frac) * (hi_r - lo_r)
        offset = cut - RHO[c]
        xb = crossing(a, cut, lambda D: S_B(D))
        x7 = crossing(a, cut, lambda D: S_7(D, N))
        res[c] = {"rho_cut": r4(cut), "offset_from_rho_c": r4(offset), "D*_B": tok(xb), "D*_M7": tok(x7)}
    return res


conc = []
for m in (8, 12):
    N = int(N5(m, "MI-1"))
    d_ps, d_cum = dps_dcum(N)
    for label, X in (("a_below_Dps", d_ps - 1), ("b_Dps", d_ps), ("b_mid", (d_ps + d_cum) // 2), ("b_Dcum_minus_1", d_cum - 1), ("b_Dcum", d_cum), ("c_Dcum_plus_1", d_cum + 1), ("c_far", min(d_cum + 10, 64))):
        for frac in ("0.001", "0.5", "0.999"):
            conc.append({"m": m, "case": label, "X": X, "rho_position_in_interval": frac, "D_ps": d_ps, "D_cum": d_cum, **concrete(m, X, frac)})
out["PTM_I_concrete_rho_cuts"] = conc

# ---------------------------------------------------------------- actual crossings (58) under each table
act = {}
for name, (kr, pf) in (("in_force", ("MI-1", "PF-2")), ("C-CEIL-T", ("ceiled", "PF-2")), ("C-PF1-T", ("MI-1", "PF-1"))):
    t = TAB[(kr, pf)]
    cnt = {"crossings": 0, "X_le_4": 0, "earlier": 0, "later": 0, "same": 0, "no_later_region": 0, "undetermined_slot": 0, "no_earlier_region": 0, "violations": 0}
    detail = []
    for m in range(M_LO, M_HI + 1):
        N = int(N5(m, kr))
        d_ps, d_cum = dps_dcum(N)
        for c in ("K-571", "B-571"):
            xb, x7 = as_int(t[(c, "R-B", m)]), as_int(t[(c, "M7", m)])
            cnt["crossings"] += 1
            cnt["earlier" if x7 < xb else "later" if x7 > xb else "same"] += 1
            if xb <= 4:
                cnt["X_le_4"] += 1
                cnt["violations"] += x7 != xb
                continue
            if d_cum is None or xb <= d_cum - 1:
                cnt["no_later_region"] += 1; cnt["violations"] += x7 > xb; reg = "no_later"
            elif xb == d_cum and delta7_sign(N, d_cum - 1) > 0:
                cnt["undetermined_slot"] += 1; reg = "undetermined"
            else:
                cnt["no_earlier_region"] += 1; cnt["violations"] += x7 < xb; reg = "no_earlier"
            if x7 != xb or reg != "no_later":
                detail.append([c, m, xb, x7, d_ps, d_cum, reg])
    act[name] = {"counts": cnt, "non_trivial": detail}
out["M7_actual_crossings"] = act
out["M7_actual_crossings_cb3"] = cb3["M7_actual_crossings"]

json.dump(out, sys.stdout, indent=1, default=str)

direction_sweep.py.source:
"""TASK-20261002-f19cfa: sweep the in-force text of version 4 (review plan
in_force_text_rule) for direction sentences. Spec, audit sheet (with embedded
logs) and worksheet are in force whole; the hypothesis contributes its
version_4 block and the earlier-layer fields its in_force_index marks
in_force. Each string leaf is split into sentences; a sentence is kept if it
contains a plan keyword ("earlier", "later", "one way", "one-way", "only",
"can only", "grows faster", "grows more slowly", "crossover", "per-step",
"cumulative"); "only" alone is kept only beside a direction cue. Output: one
JSON row per kept sentence with file, field path and the line of the field."""
import re, json, sys, yaml

ROOT = "/home/user/crypto-autoresearcher/"
FILES = {
    "spec": "experiments/EXP-NISTBIN-451dfa/specification.yaml",
    "hyp": "ledger/hypotheses/H-NISTBIN-dec5e1.yaml",
    "audit": "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-bc5bd5/design/TASK-20261002-e11714/proof-search-map-audit.yaml",
    "worksheet": "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-bc5bd5/design/TASK-20261002-e11714/revision-worksheet.yaml",
}
KW = re.compile(r"\b(earlier|later|one[- ]way|can only|grows faster|grows more slowly|crossover|per-step|cumulative)\b", re.I)
ONLY = re.compile(r"\bonly\b", re.I)
CUE = re.compile(r"\b(direction|move|moves|earlier|later|M5|M7|M8|D\*)\b")


def walk(o, p):
    if isinstance(o, dict):
        for k, v in o.items():
            yield from walk(v, f"{p}.{k}" if p else str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o):
            yield from walk(v, f"{p}[{i}]")
    elif isinstance(o, str):
        yield p, o


def sentences(s):
    s = " ".join(s.split())
    return [x.strip() for x in re.split(r"(?<=[.;:])\s+(?=[A-Z(])", s) if x.strip()]


rows = []
for key, rel in FILES.items():
    doc = yaml.safe_load(open(ROOT + rel))
    top = list(doc.values())[0]
    if key == "hyp":
        idx = top["version_4"]["supersedes_for_version_4"]["in_force_index"]
        inf = {e["path"] for e in idx if e["status"] == "in_force"}
        leaves = [(p, s) for p, s in walk(top, "") if p.startswith("version_4") or p in inf]
    else:
        leaves = list(walk(top, ""))
    for p, s in leaves:
        for sent in sentences(s):
            if KW.search(sent) or (ONLY.search(sent) and CUE.search(sent)):
                rows.append({"file": key, "path": p, "sentence": sent})
json.dump(rows, open(sys.argv[1], "w"), indent=0)
print(len(rows), "sentences kept")
from collections import Counter
print(Counter(r["file"] for r in rows))

