"""TASK-20261002-f19cfa: index-status check of every earlier-layer (v1, v2, v3)
leaf of H-NISTBIN-dec5e1 that carries an M7, binomial, E1/E2, P-S, spread,
one-way or transfer keyword: is it in_force or superseded_by_version_4 in the
version_4 in_force_index; and is every earlier-layer leaf indexed. Prints JSON."""
import yaml, re, json
doc = yaml.safe_load(open("/home/user/crypto-autoresearcher/ledger/hypotheses/H-NISTBIN-dec5e1.yaml"))["hypothesis"]
idx = doc["version_4"]["supersedes_for_version_4"]["in_force_index"]
st = {e["path"]: e["status"] for e in idx}
def walk(o, p):
    if isinstance(o, dict):
        for k, v in o.items(): yield from walk(v, f"{p}.{k}" if p else str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o): yield from walk(v, f"{p}[{i}]")
    else: yield p, o
pat = re.compile(r"\bM7\b|binomial|\bE1\b|\bE2\b|P-S|spread|one[- ]way|transfer|\bH5\b|crossings at high degree|does the second")
leaves = [(p, v) for p, v in walk(doc, "") if not p.startswith("version_4")]
hits = [{"path": p, "status": st.get(p, "NOT INDEXED"), "text": " ".join(v.split())[:240]}
        for p, v in leaves if isinstance(v, str) and pat.search(v)]
print(json.dumps({"earlier_layer_leaves": len(leaves), "not_indexed": [p for p, _ in leaves if p not in st],
                  "index_entries": len(idx), "in_force_entries": sum(1 for e in idx if e["status"] == "in_force"),
                  "keyword_leaves_in_force": [h for h in hits if h["status"] == "in_force"],
                  "keyword_leaves_superseded_count": sum(1 for h in hits if h["status"] == "superseded_by_version_4"),
                  "superseded_M7_one_way_examples": [h for h in hits if re.search(r"M7|does the second|crossings at high degree", h["text"]) and h["status"] != "in_force"][:8]}, indent=1))

lint_yaml.py.source:
"""TASK-20261002-f19cfa: parse a YAML file and lint two launch-prompt rules:
(1) prose containing ': ' only in folded/literal block scalars (no plain
scalar value containing ': '); (2) no mapping key at list-item indent and no
indentless sequence (a '- ' line at the same indent as the key introducing it)."""
import re, sys, yaml
p = sys.argv[1]
txt = open(p, encoding="utf-8").read()
doc = yaml.safe_load(txt)
print("parse: OK, top keys", list(doc))
lines = txt.split("\n")
viol = []
in_block = None
for i, l in enumerate(lines, 1):
    s = l.rstrip()
    if not s.strip() or s.strip().startswith("#"):
        continue
    ind = len(s) - len(s.lstrip(" "))
    if in_block is not None:
        if ind > in_block:
            continue
        in_block = None
    m = re.match(r"^(\s*)(- )?([A-Za-z0-9_\-\.\(\) ']+):(\s+(.*))?$", s)
    if m:
        val = (m.group(5) or "").strip()
        if val in (">-", ">", "|", "|-", ">+", "|+"):
            in_block = ind + (2 if m.group(2) else 0)
            continue
        if val and val[0] not in "[{'\"&*!" and ": " in val:
            viol.append((i, "plain scalar with ': '", s.strip()[:100]))
    elif s.lstrip().startswith("- "):
        item = s.lstrip()[2:].strip()
        if item in (">-", ">", "|", "|-"):
            in_block = ind
            continue
        if item and item[0] not in "[{'\"" and ": " in item and not re.match(r"^[A-Za-z0-9_\-]+: ", item):
            viol.append((i, "plain list scalar with ': '", s.strip()[:100]))
# rule 2: indentless sequences and keys at list-item indent
prev_key_indent = {}
for i in range(1, len(lines)):
    s = lines[i]
    if s.lstrip().startswith("- "):
        ind = len(s) - len(s.lstrip(" "))
        j = i - 1
        while j >= 0 and (not lines[j].strip() or lines[j].strip().startswith("#")):
            j -= 1
        pj = lines[j]
        pind = len(pj) - len(pj.lstrip(" "))
        if re.match(r"^\s*[A-Za-z0-9_\-]+:\s*$", pj) and pind == ind:
            viol.append((i + 1, "indentless sequence (dash at the key's indent)", s.strip()[:80]))
    m = re.match(r"^(\s*)([A-Za-z0-9_\-]+):", s)
    if m and not s.lstrip().startswith("- "):
        ind = len(m.group(1))
        j = i - 1
        while j >= 0:
            t = lines[j]
            if t.strip() and not t.strip().startswith("#"):
                tind = len(t) - len(t.lstrip(" "))
                if tind <= ind:
                    if t.lstrip().startswith("- ") and tind == ind:
                        viol.append((i + 1, "mapping key at list-item indent", s.strip()[:80]))
                    break
            j -= 1
print("violations:", len(viol))
for v in viol:
    print(v)

